<?php require __DIR__.'/../config/config.php';require __DIR__.'/../config/helpers.php';require_role('client');$uid=current_user()['id'];$q=$pdo->prepare('SELECT COUNT(*) FROM reservations WHERE user_id=?');$q->execute([$uid]);$count=$q->fetchColumn();$q=$pdo->prepare('SELECT r.*,h.nom hotel_nom,rm.nom chambre FROM reservations r JOIN hotels h ON h.id=r.hotel_id JOIN rooms rm ON rm.id=r.room_id WHERE r.user_id=? ORDER BY r.created_at DESC');$q->execute([$uid]);$reservations=$q->fetchAll();$pageTitle='Mon espace client';require __DIR__.'/../includes/header.php';?><section class="dashboard"><div class="container"><div class="dash-title"><div><span class="eyebrow">VOTRE ESPACE</span><h1>Bonjour <?=e(current_user()['prenom'])?> 👋</h1><p class="muted">Retrouvez vos séjours et vos demandes de réservation.</p></div><a class="btn btn-primary" href="<?=BASE_URL?>/index.php">Explorer les hôtels →</a></div><div class="stat-grid"><div class="stat-card"><small>Total réservations</small><strong><?=$count?></strong></div><div class="stat-card"><small>En attente</small><strong><?=count(array_filter($reservations,fn($r)=>$r['statut']==='attente'))?></strong></div><div class="stat-card"><small>Confirmées</small><strong><?=count(array_filter($reservations,fn($r)=>$r['statut']==='confirmee'))?></strong></div><div class="stat-card"><small>Favoris</small><strong><?php $q=$pdo->prepare('SELECT COUNT(*) FROM favorites WHERE user_id=?');$q->execute([$uid]);echo $q->fetchColumn();?></strong></div></div><div class="panel"><h2>Mes réservations</h2><div class="table-responsive"><table class="table"><thead><tr><th>Référence</th><th>Hôtel / chambre</th><th>Dates</th><th>Total</th><th>Statut</th><th>Action</th></tr></thead><tbody><?php foreach($reservations as $r):?><tr><td><?=e($r['code'])?></td><td><strong><?=e($r['hotel_nom'])?></strong><br><span class="muted"><?=e($r['chambre'])?></span></td><td><?=e($r['date_arrivee'])?><br>au <?=e($r['date_depart'])?></td><td><?=money($r['total'])?></td><td><span class="badge-status"><?=e($r['statut'])?></span></td><td><?php if(in_array($r['statut'],['attente','confirmee'],true)&&$r['date_arrivee']>date('Y-m-d')):?><form method="post" action="cancel.php" onsubmit="return confirm('Annuler cette réservation ?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger">Annuler</button></form><?php else:?><a class="text-link" href="<?=BASE_URL?>/hotel.php?id=<?=$r['hotel_id']?>">Voir l’hôtel</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$reservations):?><tr><td colspan="6" class="text-center muted py-4">Vous n’avez pas encore de réservation.</td></tr><?php endif;?></tbody></table></div></div></div></section><?php require __DIR__.'/../includes/footer.php';?>